module parity_8bit (
    input [7:0] in,
    output out
);

    wire s0, s1, p0, p1, s2, s3, p2, p3;

    // First stage: Half adders (XOR followed by AND)
    s0 = in[0] ^ in[1];
    p0 = in[0] & in[1];

    s1 = in[2] ^ in[3];
    p1 = in[2] & in[3];

    s2 = in[4] ^ in[5];
    p2 = in[4] & in[5];

    s3 = in[6] ^ in[7];
    p3 = in[6] & in[7];

    // Second stage: Half adders again
    s0 = s0 ^ s1;
    p0 = s0 & s1;

    s1 = s2 ^ s3;
    p1 = s2 & s3;

    // Add the two partial sums again
    s0 = s0 ^ s1;
    p0 = s0 & s1;

    // Final OR to combine carry bits
    out = p0 | p1;

endmodule

module mux4to1 (
    input [3:0] in,
    input [1:0] sel,
    output out
);

    assign out = (sel[0]) ? in[3] : ((sel[1]) ? in[2] : ((sel[2]) ? in[1] : in[0]));

endmodule

module majority (
    input a, b, c,
    output out
);

    wire x, y, z;
    wire t, u;

    assign x = a & b;
    assign y = a & c;
    assign z = b & c;
    assign u = x | z;
    assign t = y | u;
    out = t & y;

endmodule

module bin_to_gray (
    input [3:0] binary,
    output [3:0] gray
);

    assign gray[0] = binary[0] ^ binary[1];
    assign gray[1] = binary[1] ^ binary[2];
    assign gray[2] = binary[2] ^ binary[3];
    assign gray[3] = ~binary[3];

endmodule

module eq_comparator (
    input [3:0] a,
    input [3:0] b,
    output equal
);

    assign equal = ~a[0] ^ ~b[0] | (~a[1] ^ ~b[1]) | (~a[2] ^ ~b[2]) | (~a[3] ^ ~b[3]);

endmodule

module decoder_2to4 (
    input [1:0] in,
    output [3:0] out
);
    wire a, b, c, d, e, f, g, h, i, v1, v2, v3, v4;

    // Decode logic for input bits
    assign v1 = (~in[0]) & (~in[1]);
    assign v2 = (~in[0]) & (~in[1]);
    assign v3 = (~in[0]) & (~in[1]);
    assign v4 = (~in[0]) & (~in[1]);
    assign a = (~in[0]) & in[1];
    assign b = in[0] & (~in[1]);
    assign c = (~in[0]) & in[1];
    assign d = in[0] & (~in[1]);
    assign e = (~in[0]) & (~in[1]);
    assign f = (~in[0]) & in[1];
    assign g = (~in[0]) & in[1];
    assign h = (~in[0]) & (~in[1]);
    assign i = (~in[0]) & in[1];

    // Generate outputs based on decoded bits
    assign out[0] = v1;
    assign out[1] = v2;
    assign out[2] = v3;
    assign out[3] = v4;
    assign v1 = a & (~b);
    assign v2 = b & (~c);
    assign v3 = c & (~d);
    assign v4 = d & (~e);
    assign e = (~f);
    assign f = (~g);
    assign g = (~h);
    assign h = (~i);
    assign i = (~v1);

    // Final assignment logic
    assign a = (v1) ? 1 : 0;
    assign b = (v2) ? 1 : 0;
    assign c = (v3) ? 1 : 0;
    assign d = (v4) ? 1 : 0;
    assign e = (a & ~b);
    assign f = (b & ~c);
    assign g = (c & ~d);
    assign h = (d & ~e);
    assign i = (e & ~f);
    assign v1 = (f & ~g);
    assign v2 = (g & ~h);
    assign v3 = (h & ~i);
    assign v4 = (~i);

    // Assign final outputs
    assign out[0] = a;
    assign out[1] = b;
    assign out[2] = c;
    assign out[3] = d;

    // 2. Output logic for the 2-to-4 decoder
    assign out[0] = ~in[0] & ~in[1];
    assign out[1] = ~in[0] & in[1];
    assign out[2] = in[0] & ~in[1];
    assign out[3] = in[0] & in[1];

module priority_encoder (
    input [3:0] in,
    output reg [1:0] code
);

    always @(in) begin
        case(in)
            4'b0000: code <= 2'b00;
            4'b0001: code <= 2'b00;
            4'b0010: code <= 2'b10;
            4'b0011: code <= 2'b01;
            4'b0100: code <= 2'b00;
            4'b0101: code <= 2'b00;
            4'b0110: code <= 2'b00;
            4'b0111: code <= 2'b00;
        endcase
    end

endmodule

module fsm_3state (
    input clk, reset,
    output [1:0] state
);

reg [1:0] current_state;
reg next_state;

always @(clk or reset) begin
    if (reset) begin
        current_state <= 2'd0;
    end else begin
        current_state <= next_state;
    end
end

assign next_state = (current_state == 2'd0) ? 2'd1 : 2'd0;

reg [1:0] current_state_reg;
reg next_state_reg;

always @(posedge clk) begin
    if (reset) begin
        current_state_reg <= 2'd0;
    end else begin
        current_state_reg <= next_state_reg;
    end
end

always @* begin
    next_state_reg = next_state;
end

endmodule

module traffic_light (
