    wire [2:0] out_blue;
    wire [2:0] out_white;
    wire [2:0] input_1;
    wire [2:0] light_1;
    wire [2:0] light_2;
    wire [0:2] output_1;

    // Reset Logic
    AND (#) u_and1 ( reset_1, reset, 1'b0);
    NI (`NC_REG_INPUT) u_nc_reg_1 ( reset, reset_1);

    // Inverters
    NI (`NC_IN) u_nc_in1 ( in_blue2, light_2[1] );
    NI (`NC_IN) u_nc_in2 ( out_gray2, input_1[2] );
    NI (`NC_IN) u_nc_in3 ( out_gray1, input_1[0] );
    NI (`NC_IN) u_nc_in4 ( out_gray3, input_1[1] );

    // NAND Gates
    NCNDR (, out_gray1, reset_1, light_1[1]);
    NCNDR (, out_gray2, in_yellow2, out_gray1);
    NCNDR (, out_blue2, out_gray2, light_2[1]);
    NCNDR ( out_blue2, out_gray3, out_gray3, in_yellow2);

    // NOR Gates
    NCNR (, out_gray2, in_white1, out_gray1);
    NCNR (, out_gray1, light_1[1], out_gray3);
    NCNR (, out_gray3, out_gray1, light_1[1]);

    // D Latch
    D (`NCRegOut) u_nc_reg_2 ( clk, reset_1, out_blue2, out_blue2);

    // Combinational Logic
    NCNDR (input_1[1], out_blue1, out_blue1, out_gray3);
    NCNDR (input_1[0], light_2[0], in_weekday1, out_blue1);
    NCNDR ( in_blue2, light_2[0], out_gray3, out_blue2);
    NCNDR ( in_blue1, out_gray3, light_2[1], out_blue1);
    NCNDR (, in_white1, light_1[1], in_white2);
    NCNDR (, in_yellow1, in_yellow2, light_1[1]);
    NCNDR (, light_1[1], light_1[0], in_blue1);
    NCNDR (, light_1[0], light_1[1], in_blue2);

    // AND Gates
    AND (#) u_and9 ( light_1[1], in_white1, in_white2 ); // Light[0]
    AND (#) u_and10 ( light_1[0], in_blue1, in_blue2 ); // Light[1]
    AND (#) u_and11 ( in_yellow1, in_yellow2, light_1[1] ); // Light[2]

    // Assignments
    assign out_gray[0] = out_gray1;
    assign out_gray[1] = out_gray2;
    assign out_gray[2] = out_gray3;
    assign out_blue[0] = out_blue1;
    assign out_blue[1] = out_blue2;
    assign input_1[0] = in_white1;
    assign input_1[1] = in_white2;
    assign input_1[2] = out_gray2;
    assign light[0] = light_1[1];
    assign light[1] = light_1[0];
    assign light[2] = light_1[1];

endmodule

module elevator_controller (
    input clk, reset,
    input up_request, down_request,
    output [1:0] state
);

wire s_dpff_pp0_n;
wire s_dpff_pp0_n_n;
wire s_dpff_pp0_n_n_n;

// First Flip-Flop (S_dpff_pp0)
always @(posedge clk or posedge reset) begin
    if (reset) begin
        s_dpff_pp0_n <= 2'b00;
    end else begin
        s_dpff_pp0_n <= {s_dpff_pp0_n_n_n, s_dpff_pp0_n_n};
    end
end

// Second Flip-Flop (S_dpff_pp0)
always @(posedge clk or posedge reset) begin
    if (reset) begin
        s_dpff_pp0_n <= 2'b00;
    end else begin
        s_dpff_pp0_n <= {s_dpff_pp0_n_n, s_dpff_pp0_n_n_n};
    end
end

// D_ff_c_lower for lower Q output of first FF
assign s_dpff_pp0_n[1] = s_dpff_pp0_n[0] ^ down_request;

// D_ff_c_upper for upper Q output of second FF
assign s_dpff_pp0_n[0] = s_dpff_pp0_n[1] ^ up_request;

// Gate logic for completing the D_ff_c logic
assign s_dpff_pp0_n_n = ~(s_dpff_pp0_n_n[0]);
assign s_dpff_pp0_n_n_n = ~(s_dpff_pp0_n_n_n[0]);

// Assign outputs
state <= s_dpff_pp0_n;

endmodule

module vending_machine (
    input clk, reset,
    input coin_inserted, item_selected,
    output [1:0] state
);

    reg [1:0] state_reg;

    assign state = state_reg;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            state_reg <= 2'b00;
        end
        else begin
            case (state_reg)
                2'b00:
                    if (coin_inserted) state_reg <= 2'b01;
                    if (item_selected) state_reg <= 2'b10;
                break;
                2'b01:
                    if (item_selected) state_reg <= 2'b11;
                break;
                2'b10:
                    if (item_selected) state_reg <= 2'b11;
                break;
                2'b11:
                    state_reg <= 2'b00;
                break;
                default:
                    state_reg <= 2'b00;
            endcase
        end
    end

endmodule

module power (
