  wire i5, i6, i7, i8, i9, i10;

  // Encoder logic to s1 and s2
  always @(*)
    s1 = state[0];
    s2 = state[1];

  // Nand gate for Encoding
  always @(*) begin
    i1 = !state[0];
    i2 = !state[1];
    i3 = !(i1 & i2); // Combining s1 and s2 into one signal
    // Simplified setup for 3 input nand
  end

  // Nand to output b
  always @(*) begin
    i4 = !((i1 & i2) & s1);
  end

  // Nand gate for in input
  always @(*) begin
    i5 = !in;
    i6 = in || s1;
  end

  // Next state determination
  always @(*) begin
    i7 = 2'b00; // Initial next state

    if (((state[1] & (i7 | (i7 & 2'b11))))) // This will be 2'b00 or 2'b01
      i7 = 2'b01;
    else if (((state[0] & !state[1]))) // This will be 2'b00 or 2'b01
      i7 = 2'b10;
  end

  // Final Output logic
  assign out = s3;
endmodule

