  input clk,
  input areset,
  input bump_left,
  input bump_right,
  input ground,
  output walk_left,
  output walk_right,
  output aaah
);

  reg DFF_PP0;
  reg DFF_PP1;

  assign walk_left = (~DFF_PP0 & ground & bump_left) & (DFF_PP1 & bump_right);
  assign walk_right = (~DFF_PP0 & ground & bump_right) & (DFF_PP1 & bump_left);
  assign aaah = (~DFF_PP1 & bump_right | DFF_PP0 & bump_left) & bump_right;
  assign DFF_PP0 = ~DFF_PP1;
  assign DFF_PP1 = bump_right & bump_left;

  always @(negedge clk or posedge areset) begin
    if(areset) begin
      DFF_PP0 <= 1'b0;
      DFF_PP1 <= 1'b0;
