  // Reset
  always @(posedge clk or posedge reset) begin
    reset_ff <= reset;
  end

  // Shift FF
  always @(posedge clk or posedge reset) begin
    if (~reset) shift_ff <= 1'b0;
    else shift_ff <= sw_input;
  end

  // SW Input FF
  always @(posedge clk or posedge reset) begin
    if (~reset) sw_first <= 1'b0;
    else sw_first <= sw_input && sw_second;
  end

  // Second SW Input FF
  always @(posedge clk or posedge reset) begin
    if (~reset) sw_second <= 1'b0;
    else sw_second <= sw_first && sw_input;
  end

  // Logic to generate shift_ena
  assign shift_ena = shift_ff | sw_first | sw_second;

