module comparator_3bit (
    input [2:0] A,
    input [2:0] B,
    output A_greater,
    output A_equal,
    output A_less
);
    wire a2, a1, a0;
    wire b2, b1, b0;
    wire A_less_gate_out, A_equal_gate_out, A_greater_gate_out;
    wire A_equal_gate_out_temp;

    assign a2 = A[2];
    assign a1 = A[1];
    assign a0 = A[0];
    assign b2 = B[2];
    assign b1 = B[1];
    assign b0 = B[0];

    and (A_less_gate_out, a2, b2);
    or (A_equal_gate_out_temp, a2, b2);
    nand (A_less_gate_out, A_equal_gate_out_temp, ~a1);

    or (A_equal_gate_out_temp, ~b2, a1);
    or (A_equal_gate_out_temp, ~b2, ~a1);

    or (A_equal_gate_out_temp, a2, ~b2);
    or (A_equal_gate_out_temp, b1, a0);

    or (A_equal_gate_out_temp, a2, ~b1);
    and (A_equal_gate_out, a1, b0);

    and (A_greater_gate_out, ~a1, b0);
    or (A_greater_gate_out, a0, ~b0);
    nand (A_greater_gate_out, A_equal_gate_out, A_greater_gate_out);

    and (A_equal_gate_out, A_greater_gate_out, A_equal_gate_out);

    assign A_less = ~A_less_gate_out;
    assign A_equal = ~A_equal_gate_out;
    assign A_greater = ~A_greater_gate_out;
endmodule

module comparator_4bit(
