module LFSR (out, clk, rst);
  input clk, rst;
  output reg [3:0] out;

  wire reg1, reg2, reg3;

  assign reg1 = rst | reg3;
  assign reg2 = (reg1 & reg3) | (~reg1 & reg2);
  assign reg3 = reg1 | reg2;

  always @(posedge clk or posedge rst) begin
      if (rst === 1) begin
          out initially 0;
          out <= 4'b0011;
      end else begin
          out <= {reg3, reg1, reg2};
      end
  end

  initial
  begin
    out = 0;
  end
endmodule

module right_shifter(clk, q,d);  

    input  clk;  
    input d;  
    output  [7:0] q;

    reg [7:0] q;
    // q[0] is the output.
    // q[1] is sampled from d.
    // q[2..8] are shifted versions of the outputs from subsequent flip-flops.

    // Use a counter to implement shift
    reg [7:0] shift_counter;
    wire reg_in;
    wire d_short;

    assign reg_in = shift_counter[0];
    assign d_short = d;

    assign q = d_short * 2**7 - reg_in << 0;

endmodule

module synchronizer(
	input 				clk_a	, 
	input 				clk_b	,   
	input 				arstn	,
	input				brstn   ,
	input		[3:0]	data_in	,
	input               data_en ,

	output reg  [3:0] 	dataout
);

    reg q[4];
    reg en_n, en_pp;
    wire arstn_b, en;

    assign en = data_en;
    assign en_n = ~en;
    assign en_pp = ~en_n;

    // Async reset on clk_b
    always @(posedge clk_a or posedge arstn or posedge brstn) begin
        if (arstn || brstn) begin
            q[0] <= 0;
            q[1] <= 0;
            q[2] <= 0;
            q[3] <= 0;
            en_n <= 0;
        end
    end

    // First stage
    always @(posedge clk_b or posedge arstn) begin
        if (arstn) begin
            q[0] <= 0;
            en_n <= 0;
        end
        else begin
            q[0] <= ~data_in;
            en_n <= en;
        end
    end

    // Second stage
    always @(posedge clk_b or posedge arstn) begin
        if (arstn) begin
            q[1] <= 0;
        end
        else begin
            q[1] <= q[0];
        end
    end

    // Third stage
    always @(posedge clk_b or posedge arstn) begin
        if (arstn) begin
            q[2] <= 0;
        end
        else begin
            if (en_n) begin
                q[2] <= 0; // Reset if data_en is 1
            end else begin
                q[2] <= q[1];
            end
        end
    end

    // Fourth stage
    always @(posedge clk_b or posedge arstn) begin
        if (arstn) begin
            q[3] <= 0;
        end
        else begin
            if (en_pp) begin
                q[3] <= 0; // Reset if data_en is 1
            end else begin
                q[3] <= q[2];
            end
        end
    end

    // Output mux logic (simplified direct mapping for FF chain output)
    always @(posedge clk_b or posedge arstn) begin
        if (arstn) begin
            dataout <= 4'b0000;
        end
        else begin
            dataout <= q[3];
        end
    end

endmodule

