    assign v5 = (cn1 == 1) && (d[1] == 1) ? v0 : v1;

    assign v1 = (cn13 == 1) ? v2 : v0;

    assign v2 = (cn14 == 1) ? v3 : v1;
    assign v3 = (cn15 == 1) ? v4 : v2;
    assign v4 = (cn16 == 1) ? v5 : v3;
    assign v5 = (cn17 == 1) ? v4 : v2;

    assign valid_out = v5;
    assign dout = pn0;

    assign pn0 = ~(cn8 & d[0]);
    assign cn1 = pn0;
    assign cn2 = pn0;
    assign cn13 = pn1;
    assign cn14 = pn2;
    assign cn15 = pn3;
    assign cn16 = pn3;
    assign cn17 = d[0];
    assign cn8 = d[0];

endmodule

module ROM (
    input wire [7:0] addr,
    output reg [15:0] dout
);

    wire [1:0] mode;
    wire a2;

    assign mode = addr[0:1];
    assign a2 = addr[2]; 

    always @(*) begin
        case(mode)
            2'b00: begin dout = {12'b0, a2};        // Address 8-11
            2'b01: begin dout = {12'b0, ~a2};        // Address 9-12
            2'b10: begin dout = {12'b0, 1};          // Address 0-3
            2'b11: begin dout = {12'b0, 1};          // Address 1-4
        endcase
        default: begin dout = {16'b0}; end          // Unused address
    end

endmodule

module sequence_detector(
     input  clk, 
     input  rst_n,
     input  data_in, 
     output sequence_detected				
     );
	input clk, rst_n, data_in;

	// FFs: q0, q1
	reg q0, q1, q2;
	reg set0, set1;
	reg set_q0, set_q1, set_q2;
	reg clk_clear;

	// Logic gates (inherits clk_clear from previous version)
	wire gate0;
	wire gate1;
	wire gate2;

	gate0: begin
		gate0 = data_in & q0;
	end
	gate1: begin
		gate1 = data_in & (~q1);
	end
	gate2: begin
		gate2 = data_in & (~q2);
-end	

    assign f = gate0 & gate1 & gate2;

    assign set0 = data_in & ~f;
    assign set1 = data_in & f;

    assign sequence_detected = f;
endmodule
